              <dt>31 to 60 days overdue</dt>
              <dd data-testid="statement-aging-30-60">{{ a.days30To60 | money: a.currency }}</dd>
              <dt>More than 60 days overdue</dt>
              <dd data-testid="statement-aging-60-plus">{{ a.days60Plus | money: a.currency }}</dd>
